char calculate(vector<long long> curr_s, long long  curr_t) {
    int n = curr_s.size();
    vector<char> possible;

    for (char c = '!'; c <= '~'; c++) {
        long long target = curr_t ^ static_cast<long long>(c);
        for (int i = 0; i < (1ll << n); i++) {
            long long curr_sum = 0;
            for (int j = 0; j < n; j++) {
                if ((i >> j) & 1) {
                    curr_sum ^= curr_s[j];
                }
            }

            if (curr_sum == target) {
                possible.push_back(c);
            }
        }
    }
    if (possible.size() == 1) {
        return possible[0];
    }
    return '?';
}

